#!/usr/bin/env bash
greet() {
  local name="$1"
  echo "Hello, $name!"
}

greet "World"            # Hello, World!
greet                    # Hello, !   (no arg -> $1 is empty)
greet "Ada" "Bob"        # $2 is silently dropped (echo doesn't use it)

