#!/usr/bin/env bash
cleanup() {
  echo "Cleaning up..."
  rm -f /tmp/myapp.lock
}
trap cleanup EXIT   # runs on any exit (success, error, signal)

echo "Working..."
# Even if we exit early or hit an error, cleanup runs
exit 0
